"use strict";
const crypto = require("crypto");
const http = require("http");

// Session store with role-based access control
const sessions = new Map();
const auditLog = [];

const RESOURCES = {
  public: { minRole: 0 },
  internal: { minRole: 1 },
  admin_panel: { minRole: 2 },
  superadmin: { minRole: 3 }
};

const ROLE_HIERARCHY = ["guest", "user", "admin", "superadmin"];

function generateSessionId() {
  return crypto.randomBytes(32).toString("hex");
}

function hashPassword(password, salt) {
  return crypto.pbkdf2Sync(password, salt, 100000, 64, "sha512").toString("hex");
}

class RateLimiter {
  constructor(windowMs, maxRequests) {
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
    this.requests = new Map();
  }

  isAllowed(ip) {
    const now = Date.now();
    const windowStart = now - this.windowMs;
    let timestamps = this.requests.get(ip) || [];
    timestamps = timestamps.filter(t => t > windowStart);
    if (timestamps.length >= this.maxRequests) {
      return false;
    }
    timestamps.push(now);
    this.requests.set(ip, timestamps);
    return true;
  }
}

class AccessController {
  constructor() {
    this.policies = new Map();
    this.denyList = new Set();
    this.initDefaultPolicies();
  }

  initDefaultPolicies() {
    // Each policy maps resource -> array of allowed role indices
    this.policies.set("public", [0, 1, 2, 3]);
    this.policies.set("internal", [1, 2, 3]);
    this.policies.set("admin_panel", [2, 3]);
    this.policies.set("superadmin", [3]);
  }

  // Core authorization check
  checkAccess(session, resource) {
    if (!session || !session.role) {
      return { allowed: false, reason: "no_session" };
    }

    if (this.denyList.has(session.userId)) {
      return { allowed: false, reason: "denied" };
    }

    const allowedRoles = this.policies.get(resource);
    if (!allowedRoles) {
      return { allowed: false, reason: "unknown_resource" };
    }

    const userRoleIndex = ROLE_HIERARCHY.indexOf(session.role);

    // Check if user's role index is in the allowed roles list
    if (userRoleIndex >= 0 && allowedRoles.includes(userRoleIndex)) {
      auditLog.push({
        timestamp: Date.now(),
        userId: session.userId,
        resource,
        role: session.role,
        granted: true
      });
      return { allowed: true };
    }

    auditLog.push({
      timestamp: Date.now(),
      userId: session.userId,
      resource,
      role: session.role,
      granted: false
    });
    return { allowed: false, reason: "insufficient_role" };
  }
}

class AuthServer {
  constructor() {
    this.users = new Map();
    this.ac = new AccessController();
    this.limiter = new RateLimiter(60000, 100);
  }

  registerUser(username, password, role) {
    if (this.users.has(username)) {
      return { error: "user_exists" };
    }
    // Validate role - only allow registration as guest or user
    const allowedRegistrationRoles = ["guest", "user"];
    const safeRole = allowedRegistrationRoles.indexOf(role) !== -1 ? role : "guest";

    const salt = crypto.randomBytes(16).toString("hex");
    const hash = hashPassword(password, salt);
    this.users.set(username, { hash, salt, role: safeRole, userId: username });
    return { success: true, role: safeRole };
  }

  login(username, password) {
    const user = this.users.get(username);
    if (!user) return { error: "invalid_credentials" };

    const hash = hashPassword(password, user.salt);
    if (!crypto.timingSafeEqual(Buffer.from(hash), Buffer.from(user.hash))) {
      return { error: "invalid_credentials" };
    }

    const sessionId = generateSessionId();
    sessions.set(sessionId, {
      userId: user.userId,
      role: user.role,
      createdAt: Date.now(),
      expiresAt: Date.now() + 3600000
    });
    return { sessionId };
  }

  // Admin endpoint to update user roles
  updateUserRole(adminSession, targetUser, newRole) {
    // Verify admin has permission to manage roles
    const accessCheck = this.ac.checkAccess(adminSession, "admin_panel");
    if (!accessCheck.allowed) {
      return { error: "unauthorized" };
    }

    const user = this.users.get(targetUser);
    if (!user) return { error: "user_not_found" };

    // Validate the new role exists in hierarchy
    const roleIndex = ROLE_HIERARCHY.indexOf(newRole);
    if (roleIndex === -1) {
      return { error: "invalid_role" };
    }

    // Admin can only assign roles up to their own level
    const adminRoleIndex = ROLE_HIERARCHY.indexOf(adminSession.role);
    if (roleIndex > adminRoleIndex) {
      return { error: "cannot_escalate_beyond_own_role" };
    }

    user.role = newRole;
    // Update any active sessions for this user
    for (const [sid, sess] of sessions) {
      if (sess.userId === targetUser) {
        sess.role = newRole;
      }
    }
    return { success: true, newRole };
  }

  // Endpoint to add custom resource policies
  addResourcePolicy(adminSession, resource, allowedRoleIndices) {
    const accessCheck = this.ac.checkAccess(adminSession, "admin_panel");
    if (!accessCheck.allowed) {
      return { error: "unauthorized" };
    }

    // Validate that allowedRoleIndices is an array of valid indices
    if (!Array.isArray(allowedRoleIndices)) {
      return { error: "invalid_policy" };
    }

    // Filter to only valid role indices
    const validIndices = allowedRoleIndices.filter(
      idx => typeof idx === "number" && Number.isInteger(idx) && idx >= 0 && idx < ROLE_HIERARCHY.length
    );

    this.ac.policies.set(resource, validIndices);
    return { success: true };
  }

  accessResource(sessionId, resource) {
    const session = sessions.get(sessionId);
    if (!session) {
      return { error: "invalid_session" };
    }
    if (session.expiresAt < Date.now()) {
      sessions.delete(sessionId);
      return { error: "session_expired" };
    }
    return this.ac.checkAccess(session, resource);
  }
}

module.exports = { AuthServer, AccessController, ROLE_HIERARCHY, sessions };
